// officials.betterbukidnon.org (Bukidnon Officials): every elected official in Bukidnon since 2001 and the
// documented family ties between them.
//
//   data/officials.json  generated by scripts/build-data.mjs from OpenHalalan (ODbL)
//   data/families.json   curated by hand; every tie cites a published source
//   data/barangays.json  generated by scripts/build-barangays.mjs from DILG (loaded on demand)
//
// Hash routes: #/ (home) · #/places · #/place/{id} · #/barangay/{id} · #/province · #/families · #/family/{id}
//              #/officials · #/person/{id} · #/about

(function () {
  'use strict';

  const I18N = window.DYI18N;
  const t = (key, fallback, params) => (I18N ? I18N.t(key, fallback, params) : fallback);

  const POS_LABEL = {
    governor: ['dy-pos-governor', 'Governor'],
    'vice-governor': ['dy-pos-vice-governor', 'Vice Governor'],
    representative: ['dy-pos-representative', 'House Representative'],
    'board-member': ['dy-pos-board-member', 'Provincial Board Member'],
    mayor: ['dy-pos-mayor', 'Mayor'],
    'vice-mayor': ['dy-pos-vice-mayor', 'Vice Mayor'],
    councilor: ['dy-pos-councilor', 'Councilor'],
  };
  const posLabel = (p) => t(...POS_LABEL[p]);
  const TERM = 3;
  const LATEST_NOTE = 'latest';

  let D; // officials.json
  let F; // families.json
  const idx = {};
  let onResize = null; // set by the family view to refit its diagram

  // ---------- Helpers ----------

  const $ = (sel) => document.querySelector(sel);
  const esc = (s) =>
    String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const fold = (s) =>
    String(s)
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .toLowerCase();

  // Election years → "2007–2013, 2022–2028" (each term runs three years)
  function spans(years) {
    const ys = [...new Set(years)].sort((a, b) => a - b);
    const out = [];
    for (const y of ys) {
      const last = out.at(-1);
      if (last && y === last[1]) last[1] = y + TERM;
      else out.push([y, y + TERM]);
    }
    return out.map(([a, b]) => `${a}–${b}`).join(', ');
  }

  const placeName = (id) => idx.place[id]?.name ?? id;
  const personLink = (id, cls = 'dy-person') => {
    const p = idx.person[id];
    const dot = idx.tiesOf[id]?.length ? '<span class="dy-dot" aria-hidden="true"></span>' : '';
    return `${dot}<a class="${cls}" href="#/person/${esc(id)}">${esc(p.name)}</a>`;
  };
  // Breadcrumb trail, always starting at Home. items: [href, label] pairs; the current page is the h1.
  const crumbs = (...items) =>
    `<nav class="dy-crumbs" aria-label="${esc(t('dy-crumbs-label', 'You are here'))}"><a href="#/">${esc(t('dy-nav-home', 'Home'))}</a>${items
      .map(([href, label]) => ` <span aria-hidden="true">/</span> <a href="${esc(href)}">${esc(label)}</a>`)
      .join('')}</nav>`;
  const PLACES_CRUMB = () => ['#/places', t('dy-nav-places', 'Cities & Municipalities')];
  const extLink = (url, text) => `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)} <span aria-hidden="true">↗</span></a>`;

  // "Mayor of Lantapan (2007–2016)" lines for one person
  function officeLines(personId) {
    const groups = new Map();
    for (const tm of idx.termsOf[personId] ?? []) {
      const k = `${tm.position}|${tm.place ?? ''}`;
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(tm.year);
    }
    const order = Object.keys(POS_LABEL);
    return [...groups]
      .sort((a, b) => order.indexOf(a[0].split('|')[0]) - order.indexOf(b[0].split('|')[0]))
      .map(([k, years]) => {
        const [pos, place] = k.split('|');
        const where = place ? `, ${placeName(place)}` : '';
        return `${posLabel(pos)}${where} (${spans(years)})`;
      });
  }

  // Families and ties a member key belongs to. Keys are person ids from officials.json,
  // or "x-…" for relatives outside it (e.g. a senator).
  function memberName(fam, key) {
    const m = fam.members.find((m) => m.key === key);
    return m?.person ? idx.person[m.person]?.name ?? m.name : m?.name ?? key;
  }

  // ---------- Data ----------

  function buildIndex() {
    idx.place = Object.fromEntries(D.places.map((p) => [p.id, p]));
    idx.person = Object.fromEntries(D.people.map((p) => [p.id, p]));
    idx.fix = Object.fromEntries(D.fixes.map((f) => [f.id, f]));
    idx.termsOf = {};
    for (const tm of D.terms) (idx.termsOf[tm.person] ??= []).push(tm);
    idx.family = Object.fromEntries(F.families.map((f) => [f.id, f]));
    idx.familiesOf = {};
    idx.tiesOf = {}; // person id → [{fam, tie, other, role}]
    let ties = 0;
    for (const fam of F.families) {
      for (const m of fam.members) {
        if (m.person) (idx.familiesOf[m.person] ??= new Set()).add(fam.id);
        if (m.person && m.photo) (idx.photoOf ??= {})[m.person] = m.photo;
      }
      for (const tie of fam.ties) {
        ties++;
        const pa = fam.members.find((m) => m.key === tie.a)?.person;
        const pb = fam.members.find((m) => m.key === tie.b)?.person;
        // On A's page the relative is B, described by B's role ("son"), and vice versa.
        if (pa) (idx.tiesOf[pa] ??= []).push({ fam, tie, other: tie.b, role: tie.bIs });
        if (pb) (idx.tiesOf[pb] ??= []).push({ fam, tie, other: tie.a, role: tie.aIs });
      }
    }
    idx.tieCount = ties;
    idx.latest = D.years.at(-1);
  }

  // Runs of consecutive terms in one seat: [{person, years}] or [{gap: year}]
  function seatRuns(place, position) {
    const out = [];
    for (const y of D.years) {
      const tms = D.terms.filter((tm) => tm.place === place && tm.position === position && tm.year === y);
      const last = out.at(-1);
      if (!tms.length) {
        if (last?.gap) last.years.push(y);
        else out.push({ gap: true, years: [y] });
        continue;
      }
      const pid = tms[0].person;
      if (last && last.person === pid) last.years.push(y);
      else out.push({ person: pid, years: [y] });
    }
    return out;
  }

  // ---------- Views: Mayors ----------

  function renderHome() {
    $('#stat-people').textContent = D.people.length.toLocaleString();
    $('#stat-families').textContent = F.families.length;
    $('#stat-ties').textContent = idx.tieCount;
    const latestMayors = D.terms.filter((tm) => tm.position === 'mayor' && tm.year === idx.latest);
    const tied = latestMayors.filter((tm) => idx.tiesOf[tm.person]?.length).length;
    $('#stat-tied').textContent = `${tied} / ${D.places.length}`;
  }

  function renderMayors() {
    const q = fold($('#m-search').value.trim());
    const district = $('#m-district').value;
    const onlyTied = $('#m-tied').checked;
    const rows = [];
    for (const place of D.places) {
      if (district && place.district !== district) continue;
      const runs = seatRuns(place.id, 'mayor');
      const mayors = runs.filter((r) => r.person).map((r) => r.person);
      const familyIds = new Set(mayors.flatMap((pid) => [...(idx.familiesOf[pid] ?? [])]));
      if (onlyTied && !familyIds.size) continue;
      if (q && !fold(place.name).includes(q) && !mayors.some((pid) => fold(idx.person[pid].name).includes(q))) continue;

      const runHtml = runs
        .slice()
        .reverse()
        .map((r) =>
          r.gap
            ? `<li><span class="dy-years">${r.years.join(', ')}</span><span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span></li>`
            : `<li><span class="dy-years">${spans(r.years)}</span><span>${personLink(r.person)}</span></li>`,
        )
        .join('');

      const ties = mayors
        .flatMap((pid) => (idx.tiesOf[pid] ?? []).map((x) => ({ pid, ...x })))
        .filter((x, i, all) => all.findIndex((y) => y.pid === x.pid && y.other === x.other) === i);
      const tieHtml = ties.length
        ? `<ul class="dy-runs">${ties
            .slice(0, 6)
            .map(
              (x) =>
                `<li style="grid-template-columns:minmax(0,1fr)"><span>${esc(idx.person[x.pid].name)}: <span class="dy-tie-role">${esc(roleLabel(x.role))}</span> ${esc(memberName(x.fam, x.other))}</span></li>`,
            )
            .join('')}${ties.length > 6 ? `<li style="grid-template-columns:minmax(0,1fr)"><a href="#/place/${place.id}">${esc(t('dy-more', '+{n} more', { n: ties.length - 6 }))}</a></li>` : ''}</ul>
           <div class="dy-chips" style="margin-top:6px">${[...familyIds].map((f) => familyChip(f)).join('')}</div>`
        : `<span class="dy-none">${esc(t('dy-no-ties', 'None documented yet'))}</span>`;

      rows.push(`<tr>
        <td><a class="dy-person" href="#/place/${place.id}">${esc(place.name)}</a>
          <span class="dy-sub">${esc(t('dy-district-n', '{d} district', { d: place.district }))}</span></td>
        <td><ul class="dy-runs">${runHtml}</ul></td>
        <td>${tieHtml}</td>
      </tr>`);
    }
    $('#mayor-rows').innerHTML = rows.join('');
    $('#mayor-empty').hidden = rows.length > 0;
  }

  const familyChip = (fid) => `<a class="dy-chip" href="#/family/${esc(fid)}">${esc(idx.family[fid].name)}</a>`;

  const ROLES = {
    father: 'Father', mother: 'Mother', son: 'Son', daughter: 'Daughter', child: 'Child', parent: 'Parent',
    husband: 'Husband', wife: 'Wife', spouse: 'Spouse', brother: 'Brother', sister: 'Sister', sibling: 'Sibling',
    grandfather: 'Grandfather', grandmother: 'Grandmother', grandson: 'Grandson', granddaughter: 'Granddaughter',
    uncle: 'Uncle', aunt: 'Aunt', nephew: 'Nephew', niece: 'Niece', cousin: 'Cousin',
    'father-in-law': 'Father-in-law', 'mother-in-law': 'Mother-in-law', 'son-in-law': 'Son-in-law',
    'daughter-in-law': 'Daughter-in-law', 'brother-in-law': 'Brother-in-law', 'sister-in-law': 'Sister-in-law', relative: 'Relative',
  };
  const roleLabel = (r) => t(`dy-role-${r}`, ROLES[r] ?? r);

  // ---------- Views: Place ----------

  function renderPlace(id) {
    const place = idx.place[id];
    if (!place) return notFound();
    const at = (pos, y) => D.terms.filter((tm) => tm.place === id && tm.position === pos && tm.year === y);
    const latest = idx.latest;
    const cur = (pos) => at(pos, latest).map((tm) => personLink(tm.person)).join(', ') || `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`;

    const byYear = D.years
      .slice()
      .reverse()
      .map((y) => {
        const m = at('mayor', y);
        const v = at('vice-mayor', y);
        const c = at('councilor', y);
        const gap = `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`;
        return `<tr>
          <td class="dy-year">${y}</td>
          <td>${m.map((tm) => personLink(tm.person)).join(', ') || gap}</td>
          <td>${v.map((tm) => personLink(tm.person)).join(', ') || gap}</td>
          <td class="dy-hide-sm"><div class="dy-councils">${c.map((tm) => `<span>${personLink(tm.person)}</span>`).join('') || gap}</div></td>
        </tr>`;
      })
      .join('');

    // Families with any member holding office here
    const here = new Set(D.terms.filter((tm) => tm.place === id).map((tm) => tm.person));
    const fams = F.families.filter((f) => f.members.some((m) => m.person && here.has(m.person)) || (f.places ?? []).includes(id));
    const tieItems = [...here]
      .flatMap((pid) => (idx.tiesOf[pid] ?? []).map((x) => ({ pid, ...x })))
      .filter((x, i, all) => all.findIndex((y) => y.tie === x.tie) === i);

    const fixes = [...new Set(D.terms.filter((tm) => tm.place === id && tm.fix).map((tm) => tm.fix))];
    const unplaced = D.terms.filter((tm) => !tm.place && tm.placeCandidates?.includes(id));

    $('#place-body').innerHTML = `
      ${crumbs(PLACES_CRUMB())}
      <h1 class="dy-h1">${esc(place.name)}</h1>
      <p class="dy-lede">${esc(
        place.type === 'city'
          ? t('dy-place-city', 'Component city, {d} congressional district of Bukidnon.', { d: place.district })
          : t('dy-place-mun', 'Municipality, {d} congressional district of Bukidnon.', { d: place.district }),
      )}</p>

      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-current', 'Elected in {y}', { y: latest }))}</h2>
        <table class="dy-table"><tbody>
          <tr><td class="dy-pos">${esc(posLabel('mayor'))}</td><td>${cur('mayor')}</td></tr>
          <tr><td class="dy-pos">${esc(posLabel('vice-mayor'))}</td><td>${cur('vice-mayor')}</td></tr>
          <tr><td class="dy-pos">${esc(t('dy-pos-councilors', 'Councilors'))}</td><td><div class="dy-councils">${at('councilor', latest)
            .map((tm) => `<span>${personLink(tm.person)}</span>`)
            .join('')}</div></td></tr>
        </tbody></table>
      </section>

      <section class="dy-block" id="brgy-section" aria-busy="true">
        <h2 class="dy-section-h">${esc(t('dy-brgy-h', 'Barangay Officials Today'))}</h2>
        <p class="dy-count">${esc(t('dy-loading', 'Loading…'))}</p>
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-ties-here', 'Documented Family Ties'))}</h2>
        ${
          tieItems.length
            ? `<ul class="dy-ties">${tieItems.map((x) => tieItem(x.fam, x.tie)).join('')}</ul><div class="dy-chips" style="margin-top:10px">${fams.map((f) => familyChip(f.id)).join('')}</div>`
            : `<p class="dy-none">${esc(t('dy-no-ties-place', 'No family ties documented for officials here yet. If you know of one with a published source, report it.'))}</p>`
        }
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-by-election', 'Winners by Election'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr>
            <th scope="col">${esc(t('dy-col-year', 'Year'))}</th>
            <th scope="col">${esc(posLabel('mayor'))}</th>
            <th scope="col">${esc(posLabel('vice-mayor'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-pos-councilors', 'Councilors'))}</th>
          </tr></thead>
          <tbody>${byYear}</tbody>
        </table></div>
        ${fixes.map((f) => `<p class="dy-note">${esc(t('dy-fix-note', 'Corrected:'))} ${esc(idx.fix[f].reason)}</p>`).join('')}
        ${
          unplaced.length
            ? `<p class="dy-note">${esc(
                t('dy-unplaced-note', 'These winners are filed under the wrong place in the source and could not be placed with certainty. They belong to {places}:', {
                  places: [...new Set(unplaced.flatMap((tm) => tm.placeCandidates))].map(placeName).join(' or '),
                }),
              )} ${unplaced.map((tm) => `${personLink(tm.person)} (${tm.year} ${esc(posLabel(tm.position))})`).join(', ')}</p>`
            : ''
        }
      </section>`;
    renderBarangays(id);
  }

  // ---------- Barangay officials (DILG snapshot, loaded on demand) ----------

  let brgyData = null;
  const loadBarangays = () =>
    (brgyData ??= fetch('data/barangays.json').then((r) => (r.ok ? r.json() : Promise.reject(new Error('barangays.json')))));
  const BRGY_ROLE = {
    captain: ['dy-brgy-captain', 'Punong barangay'],
    kagawad: ['dy-brgy-kagawads', 'Kagawads'],
    'sk-chair': ['dy-brgy-sk', 'SK chairperson'],
    'sk-member': ['dy-brgy-sk-members', 'SK members'],
  };
  const BRGY_FIRST = 12;
  const MANY = new Set(['kagawad', 'sk-member']);
  const ordinal = (n) => n + (['th', 'st', 'nd', 'rd'][n % 100 > 10 && n % 100 < 14 ? 0 : n % 10] ?? 'th');
  // "1st term" in the present position, as DILG records it
  const termTag = (o) => (o.term ? `<span class="dy-term">${esc(t('dy-term-n', '{o} term', { o: ordinal(o.term), n: o.term }))}</span>` : '');

  async function renderBarangays(placeId) {
    let B;
    try {
      B = await loadBarangays();
    } catch {
      brgyData = null;
      const sec = $('#brgy-section');
      if (sec) {
        sec.removeAttribute('aria-busy');
        sec.querySelector('.dy-count').textContent = t('dy-brgy-error', 'Barangay officials could not be loaded. Try reloading the page.');
      }
      return;
    }
    const sec = $('#brgy-section');
    if (!sec || location.hash.split('/')[2] !== placeId) return; // navigated away meanwhile
    const list = B.places[placeId] ?? [];
    const date = new Date(B.pulledAt + 'T00:00:00').toLocaleDateString(I18N?.lang?.() === 'fil' ? 'fil-PH' : 'en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
    const names = (b, role) => b.officials.filter((o) => o.role === role).map((o) => o.name);
    const row = (b, role) => {
      const ns = names(b, role);
      return `<div class="dy-brgy-row${MANY.has(role) ? ' dy-brgy-kag' : ''}"><dt>${esc(t(...BRGY_ROLE[role]))}</dt><dd>${ns.length ? ns.map(esc).join(MANY.has(role) ? ' · ' : ', ') : `<span class="dy-gap">${esc(t('dy-brgy-none', 'Not listed'))}</span>`}</dd></div>`;
    };
    const card = (b) => `<li class="dy-brgy" data-q="${esc(fold([b.name, ...b.officials.map((o) => o.name)].join(' ')))}">
        <h3 class="dy-brgy-name"><a href="#/barangay/${esc(b.id)}">${esc(b.name)}</a></h3>
        <dl>${row(b, 'captain')}${row(b, 'kagawad')}${row(b, 'sk-chair')}${row(b, 'sk-member')}</dl>
      </li>`;
    const sks = list.filter((b) => names(b, 'sk-chair').length).length;

    sec.removeAttribute('aria-busy');
    sec.innerHTML = `
      <h2 class="dy-section-h">${esc(t('dy-brgy-h', 'Barangay Officials Today'))}</h2>
      <p class="dy-lede-sm">${esc(t('dy-brgy-lede', '{n} barangays. Punong barangay, kagawads, SK chairperson and SK members as the DILG lists them.', { n: list.length }))}</p>
      <p class="dy-note dy-note-plain">${esc(t('dy-brgy-term', 'They were elected on 30 October 2023. RA 12232 and RA 12326 extended their term to the November 2028 elections; RA 12326 is being challenged before the Supreme Court.'))} ${esc(t('dy-brgy-note', 'A snapshot taken {date}. It shows who holds office now, with no past officials, so it is kept apart from the election history above. It is not used as evidence of family ties.', { date }))} ${extLink(B.source.url, t('dy-brgy-source', 'DILG Barangay Officials Directory'))}</p>
      ${
        list.length
          ? `<div class="dy-toolbar" style="margin-top:14px">
              <div class="dy-filter">
                <label for="b-search">${esc(t('dy-brgy-search', 'Find a barangay or a name'))}</label>
                <input id="b-search" type="search" placeholder="${esc(t('dy-brgy-search-ph', 'e.g. {b}', { b: list[0].name }))}" autocomplete="off" />
              </div>
            </div>
            <p class="dy-count" id="b-count" aria-live="polite"></p>
            <ul class="dy-brgys" id="b-list">${list.map(card).join('')}</ul>
            <div class="dy-empty" id="b-empty" hidden>${esc(t('dy-empty', 'Nothing matches.'))}</div>
            <p><button type="button" class="dy-btn dy-btn-sm" id="b-more" hidden></button></p>`
          : `<p class="dy-none">${esc(t('dy-brgy-missing', 'DILG lists no barangay officials for this place.'))}</p>`
      }`;
    if (!list.length) return;

    let all = false;
    const apply = () => {
      const q = fold($('#b-search').value.trim());
      const items = [...sec.querySelectorAll('.dy-brgy')];
      let shown = 0;
      let matches = 0;
      for (const li of items) {
        const hit = !q || li.dataset.q.includes(q);
        if (hit) matches++;
        const show = hit && (q || all || shown < BRGY_FIRST);
        li.hidden = !show;
        if (show) shown++;
      }
      $('#b-count').textContent = q
        ? t('dy-brgy-count-q', '{n} of {total} barangays match', { n: matches, total: items.length })
        : t('dy-brgy-count', '{n} barangays · {s} with an SK chairperson listed', { n: items.length, s: sks });
      $('#b-empty').hidden = matches > 0;
      const more = $('#b-more');
      more.hidden = !!q || items.length <= BRGY_FIRST;
      more.textContent = all ? t('dy-show-fewer', 'Show fewer') : t('dy-brgy-show-all', 'Show all {n} barangays', { n: items.length });
    };
    $('#b-search').addEventListener('input', apply);
    $('#b-more').addEventListener('click', () => {
      all = !all;
      apply();
    });
    apply();
  }

  // ---------- Find your barangay ----------

  // id ("12-001") → { b, place }, built once barangays.json is in
  let brgyIndex = null;
  async function barangayIndex() {
    if (brgyIndex) return brgyIndex;
    const B = await loadBarangays();
    const byId = {};
    const all = [];
    for (const [place, list] of Object.entries(B.places)) {
      for (const b of list) {
        const e = { b, place, key: fold(b.name), placeKey: fold(placeName(place)) };
        byId[b.id] = e;
        all.push(e);
      }
    }
    brgyIndex = { B, byId, all };
    return brgyIndex;
  }

  function finderHtml(pre, { big = false } = {}) {
    return `<div class="dy-finder${big ? ' dy-finder-big' : ''}" id="${pre}">
      <label class="dy-label" for="${pre}-q">${esc(t('dy-finder-label', 'Find your barangay'))}</label>
      <div class="dy-finder-box">
        <input id="${pre}-q" type="search" autocomplete="off" spellcheck="false" role="combobox" aria-autocomplete="list"
          aria-expanded="false" aria-controls="${pre}-list" placeholder="${esc(t('dy-finder-ph', 'Type a barangay, e.g. Sumpong'))}" />
        <ul class="dy-finder-list" id="${pre}-list" role="listbox" hidden></ul>
      </div>
      <p class="dy-finder-help">${esc(t('dy-finder-help', 'See who represents you, from your barangay captain to the governor.'))}</p>
    </div>`;
  }

  function wireFinder(pre) {
    const input = $(`#${pre}-q`);
    const list = $(`#${pre}-list`);
    if (!input) return;
    let items = [];
    let active = -1;
    const close = () => {
      list.hidden = true;
      input.setAttribute('aria-expanded', 'false');
      input.removeAttribute('aria-activedescendant');
      active = -1;
    };
    const mark = (i) => {
      active = i;
      list.querySelectorAll('[role=option]').forEach((li, j) => li.setAttribute('aria-selected', String(j === i)));
      if (i >= 0) input.setAttribute('aria-activedescendant', `${pre}-o${i}`);
      else input.removeAttribute('aria-activedescendant');
    };
    const go = (e) => {
      close();
      location.hash = `#/barangay/${encodeURIComponent(e.b.id)}`;
    };
    const update = async () => {
      const raw = input.value.trim();
      const q = fold(raw);
      if (!q) return close();
      let I;
      try {
        I = await barangayIndex();
      } catch {
        list.innerHTML = `<li class="dy-finder-empty">${esc(t('dy-brgy-error', 'Barangay officials could not be loaded. Try reloading the page.'))}</li>`;
        list.hidden = false;
        return;
      }
      if (fold(input.value.trim()) !== q) return; // typed on meanwhile
      // Barangay names first (starts-with, then contains), then matches on the town name.
      const words = q.split(/\s+/);
      const score = (e) => {
        const hay = `${e.key} ${e.placeKey}`;
        if (!words.every((w) => hay.includes(w))) return -1;
        if (e.key.startsWith(q)) return 0;
        if (e.key.includes(q)) return 1;
        return 2;
      };
      items = I.all
        .map((e) => [score(e), e])
        .filter(([s]) => s >= 0)
        .sort((a, b) => a[0] - b[0] || a[1].b.name.localeCompare(b[1].b.name) || a[1].placeKey.localeCompare(b[1].placeKey))
        .slice(0, 8)
        .map(([, e]) => e);
      list.innerHTML = items.length
        ? items
            .map(
              (e, i) =>
                `<li role="option" id="${pre}-o${i}" aria-selected="false" data-i="${i}"><span class="dy-finder-b">${esc(e.b.name)}</span><span class="dy-finder-p">${esc(placeName(e.place))}</span></li>`,
            )
            .join('')
        : `<li class="dy-finder-empty">${esc(t('dy-finder-none', 'No barangay in Bukidnon matches “{q}”.', { q: raw }))}</li>`;
      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      mark(items.length ? 0 : -1);
    };
    input.addEventListener('input', update);
    input.addEventListener('focus', () => {
      barangayIndex().catch(() => {});
      if (input.value.trim()) update();
    });
    input.addEventListener('keydown', (e) => {
      if (list.hidden) return;
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        if (!items.length) return;
        mark((active + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length);
        $(`#${pre}-o${active}`)?.scrollIntoView({ block: 'nearest' });
      } else if (e.key === 'Enter' && active >= 0) {
        e.preventDefault();
        go(items[active]);
      } else if (e.key === 'Escape') {
        close();
      }
    });
    // mousedown so the choice lands before the input blurs
    list.addEventListener('mousedown', (e) => {
      const li = e.target.closest('[role=option]');
      if (!li) return;
      e.preventDefault();
      go(items[Number(li.dataset.i)]);
    });
    input.addEventListener('blur', () => setTimeout(close, 100));
  }

  // One elected official as a small card: face, name, office
  function officialCard(pid, label) {
    const p = idx.person[pid];
    const tied = idx.tiesOf[pid]?.length;
    return `<li class="dy-off">
      ${face({ name: p.name, last: p.last, photo: idx.photoOf?.[pid] }, 'dy-face-md')}
      <span class="dy-off-body">
        <a class="dy-person" href="#/person/${esc(pid)}">${esc(p.name)}</a>
        <span class="dy-off-pos">${esc(label)}</span>
        ${tied ? `<span class="dy-pill dy-pill-on">${esc(t('dy-off-tied', 'Documented relative in office'))}</span>` : ''}
      </span>
    </li>`;
  }

  async function renderBarangay(id) {
    const body = $('#barangay-body');
    body.innerHTML = `<p class="dy-count">${esc(t('dy-loading', 'Loading…'))}</p>`;
    let I;
    try {
      I = await barangayIndex();
    } catch {
      body.innerHTML = `<p class="dy-empty">${esc(t('dy-brgy-error', 'Barangay officials could not be loaded. Try reloading the page.'))}</p>`;
      return;
    }
    if (decodeURIComponent(location.hash.split('/')[2] ?? '') !== id) return; // navigated away meanwhile
    const e = I.byId[id];
    if (!e) return notFound();
    const { b, place: pid } = e;
    const place = idx.place[pid];
    const y = idx.latest;
    const at = (pos, where) => D.terms.filter((tm) => tm.year === y && tm.position === pos && (where === undefined || tm.place === where));
    const date = new Date(I.B.pulledAt + 'T00:00:00').toLocaleDateString(I18N?.lang?.() === 'fil' ? 'fil-PH' : 'en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
    const of = (role) => b.officials.filter((o) => o.role === role);
    const none = `<span class="dy-gap">${esc(t('dy-brgy-none', 'Not listed'))}</span>`;
    // Name on the left, term on the right, so the term never reads as part of the name.
    const named = (o) => `<span class="dy-named"><span class="dy-named-n">${esc(o.name)}</span>${termTag(o)}</span>`;
    const lead = (role) => of(role).map(named).join('') || none;
    const list = (role) => of(role).map((o) => `<li>${named(o)}</li>`).join('') || `<li>${none}</li>`;
    const cards = (pos, label, where) => at(pos, where).map((tm) => officialCard(tm.person, label)).join('');
    const nameList = (pos, where) =>
      at(pos, where)
        .map((tm) => `<li>${personLink(tm.person)}</li>`)
        .join('') || `<li>${none}</li>`;
    const placeLabel = place.type === 'city' ? t('dy-layer-city', 'City') : t('dy-layer-mun', 'Municipality');

    body.innerHTML = `
      ${crumbs(PLACES_CRUMB(), [`#/place/${pid}`, place.name])}
      ${finderHtml('bf')}

      <ol class="dy-layers">
        <li class="dy-layer dy-layer-you">
          <p class="dy-label">${esc(t('dy-layer-brgy', 'Your barangay'))}</p>
          <h1 class="dy-h1 dy-layer-h">${esc(t('dy-brgy-title', 'Barangay {b}', { b: b.name }))}</h1>
          <p class="dy-layer-sub">${esc(place.name)}, Bukidnon</p>
          <div class="dy-brgy-cols">
            <div>
              <dl class="dy-brgy-lead"><dt>${esc(t('dy-brgy-captain', 'Punong barangay'))}</dt><dd>${lead('captain')}</dd></dl>
              <h2 class="dy-brgy-sub">${esc(t('dy-brgy-kagawads-long', 'Sangguniang Barangay Members (Kagawads)'))}</h2>
              <ul class="dy-brgy-names">${list('kagawad')}</ul>
            </div>
            <div>
              <dl class="dy-brgy-lead"><dt>${esc(t('dy-brgy-sk', 'SK chairperson'))}</dt><dd>${lead('sk-chair')}</dd></dl>
              <h2 class="dy-brgy-sub">${esc(t('dy-brgy-sk-members-long', 'Sangguniang Kabataan Members'))}</h2>
              <ul class="dy-brgy-names">${list('sk-member')}</ul>
              <p class="dy-note dy-note-plain">${esc(t('dy-brgy-sk-note', 'The SK chairperson heads the Sangguniang Kabataan and sits on the barangay council.'))}</p>
            </div>
          </div>
          <p class="dy-layer-src">${esc(t('dy-brgy-term', 'They were elected on 30 October 2023. RA 12232 and RA 12326 extended their term to the November 2028 elections; RA 12326 is being challenged before the Supreme Court.'))} ${esc(t('dy-brgy-src', 'From the DILG masterlist downloaded {date}. Terms are in the present position. Vacancies filled since then may not show yet.', { date }))} ${extLink(I.B.source.url, t('dy-brgy-source', 'DILG Barangay Officials Directory'))}</p>
        </li>

        <li class="dy-layer">
          <p class="dy-label">${esc(placeLabel)}</p>
          <h2 class="dy-h1 dy-layer-h"><a href="#/place/${esc(pid)}">${esc(place.name)}</a></h2>
          <p class="dy-layer-sub">${esc(t('dy-district-n', '{d} district', { d: place.district }))}</p>
          <ul class="dy-offs">${cards('mayor', posLabel('mayor'), pid)}${cards('vice-mayor', posLabel('vice-mayor'), pid)}</ul>
          <h3 class="dy-brgy-sub">${esc(t('dy-pos-councilors', 'Councilors'))}</h3>
          <ul class="dy-brgy-names">${nameList('councilor', pid)}</ul>
          <p class="dy-layer-src">${esc(t('dy-layer-elected', 'Elected in May {y}. Source: OpenHalalan.', { y }))} <a href="#/place/${esc(pid)}">${esc(t('dy-layer-history', 'Every official of {p} since 2001', { p: place.name }))}</a></p>
        </li>

        <li class="dy-layer">
          <p class="dy-label">${esc(t('dy-layer-province', 'Province'))}</p>
          <h2 class="dy-h1 dy-layer-h"><a href="#/province">Bukidnon</a></h2>
          <p class="dy-layer-sub">${esc(t('dy-region-x', 'Northern Mindanao (Region X)'))}</p>
          <ul class="dy-offs">${cards('governor', posLabel('governor'))}${cards('vice-governor', posLabel('vice-governor'))}</ul>
          <h3 class="dy-brgy-sub">${esc(t('dy-layer-reps', 'House Representatives'))}</h3>
          <p class="dy-note dy-note-plain">${esc(t('dy-layer-reps-note', '{p} is in the {d} district. The source does not say which district each representative won, so all are listed.', { p: place.name, d: place.district }))}</p>
          <ul class="dy-offs">${cards('representative', posLabel('representative'))}</ul>
          <h3 class="dy-brgy-sub">${esc(t('dy-layer-board', 'Provincial Board Members'))}</h3>
          <ul class="dy-brgy-names">${nameList('board-member')}</ul>
          <p class="dy-layer-src">${esc(t('dy-layer-elected', 'Elected in May {y}. Source: OpenHalalan.', { y }))} <a href="#/province">${esc(t('dy-layer-province-all', 'Every provincial official since 2001'))}</a></p>
        </li>
      </ol>`;
    wireFinder('bf');
    setTitle();
  }

  // One documented tie, with its sources
  // opts.i: tie index (for highlighting on the family page); opts.bare: no family label
  function tieItem(fam, tie, opts = {}) {
    const link = (key, name) => {
      const pid = fam.members.find((m) => m.key === key)?.person;
      return pid ? `<a class="dy-person" href="#/person/${esc(pid)}">${esc(name)}</a>` : `<strong>${esc(name)}</strong>`;
    };
    // The sentence is translated with placeholders, escaped, then the links go in.
    const sentence = tieSentence(fam, tie, link);
    return `<li${opts.i != null ? ` data-tie="${opts.i}"` : ''}>
      ${opts.bare ? '' : `<span class="dy-tie-role">${esc(familyLabel(fam))}</span>`}
      <span class="dy-tie-who">${sentence}</span>
      ${tie.note ? `<p class="dy-note">${esc(tie.note)}</p>` : ''}
      ${sourcesHtml(tie.sources)}
    </li>`;
  }

  const familyLabel = (fam) => t('dy-family-of', '{name} Family', { name: fam.name });

  function sourcesHtml(sources) {
    if (!sources?.length) return '';
    const quotes = sources.filter((s) => s.quote);
    return `${quotes.map((s) => `<p class="dy-quote">“${esc(s.quote)}” <span class="dy-count">${esc(s.publisher)}</span></p>`).join('')}<div class="dy-cite"><span class="dy-cite-label">${esc(
      t('dy-sources', 'Sources'),
    )}</span>${sources
      .map(
        (s) =>
          `<span class="dy-cite-item">${extLink(s.url, [s.publisher, s.date].filter(Boolean).join(', ') || s.title)}${
            s.archived ? ` <a class="dy-cite-arch" href="${esc(s.archived)}" target="_blank" rel="noopener">${esc(t('dy-archived', 'archived copy'))}</a>` : ''
          }</span>`,
      )
      .join('')}</div>`;
  }

  // ---------- Views: Province ----------

  function renderProvince() {
    const rowsFor = (positions) =>
      D.years
        .slice()
        .reverse()
        .map((y) => {
          const cells = positions.map((pos) => {
            const tms = D.terms.filter((tm) => tm.position === pos && tm.year === y);
            const list = tms.map((tm) => `<span>${personLink(tm.person)}</span>`).join('');
            return `<td><div class="dy-councils">${list || `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`}</div></td>`;
          });
          return `<tr><td class="dy-year">${y}</td>${cells.join('')}</tr>`;
        })
        .join('');
    $('#province-body').innerHTML = `
      ${crumbs()}
      <h1 class="dy-h1">${esc(t('dy-nav-province', 'Province'))}</h1>
      <p class="dy-lede">${esc(t('dy-province-desc', 'Governors, vice governors, House representatives and provincial board members elected in Bukidnon since 2001.'))}</p>
      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-gov-vg', 'Governor and Vice Governor'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(posLabel('governor'))}</th><th scope="col">${esc(posLabel('vice-governor'))}</th></tr></thead>
          <tbody>${rowsFor(['governor', 'vice-governor'])}</tbody></table></div>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-reps', 'House Representatives'))}</h2>
        <p class="dy-block-sub">${esc(t('dy-reps-note', 'Bukidnon had three districts until 2013 and four since. The source does not say which district each representative won.'))}</p>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(t('dy-reps', 'House Representatives'))}</th></tr></thead>
          <tbody>${rowsFor(['representative'])}</tbody></table></div>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-board', 'Provincial Board (Sangguniang Panlalawigan)'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(t('dy-board-members', 'Elected board members'))}</th></tr></thead>
          <tbody>${rowsFor(['board-member'])}</tbody></table></div>
      </section>`;
  }

  // ---------- Faces ----------
  // A portrait appears only when families.json gives one with its credit (members[].photo),
  // e.g. official House of Representatives portraits. Everyone else gets their initials.

  function initials(name, last) {
    const words = String(name)
      .replace(/"[^"]*"/g, ' ')
      .replace(/\b(Jr|Sr|II|III|IV)\b\.?/g, ' ')
      .split(/[\s.]+/)
      .filter((w) => /^\p{L}/u.test(w) && w.length > 1);
    const l = last ? last.replace(/^(dela|de la|del|de)\s+/i, '') : words.at(-1) ?? '';
    return ((words[0]?.[0] ?? '') + (l[0] ?? '')).toUpperCase();
  }

  // x: { name, last, photo }
  function face(x, cls = '') {
    const img = x.photo ? `<img src="${esc(x.photo.url)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : '';
    return `<span class="dy-face ${cls}" aria-hidden="true">${esc(initials(x.name, x.last))}${img}</span>`;
  }

  const cap = (s) => (s ? s[0].toUpperCase() + s.slice(1) : s);
  const PROVINCIAL = new Set(['governor', 'vice-governor', 'representative', 'board-member']);
  const SHORT = {
    governor: ['dy-short-governor', 'Gov'],
    'vice-governor': ['dy-short-vice-governor', 'VGov'],
    representative: ['dy-short-representative', 'Rep'],
    'board-member': ['dy-short-board-member', 'BM'],
    mayor: ['dy-short-mayor', 'May'],
    'vice-mayor': ['dy-short-vice-mayor', 'VM'],
    councilor: ['dy-short-councilor', 'Cou'],
  };

  // Highest office held, first to last year: "Governor, 2001–2022"
  function shortOffice(pid) {
    const tms = idx.termsOf[pid] ?? [];
    if (!tms.length) return '';
    const order = Object.keys(POS_LABEL);
    const top = tms.reduce((a, b) => (order.indexOf(b.position) < order.indexOf(a.position) ? b : a));
    const ys = tms.filter((tm) => tm.position === top.position).map((tm) => tm.year);
    return `${posLabel(top.position)}, ${Math.min(...ys)}–${Math.max(...ys) + TERM}`;
  }

  function memberInfo(m) {
    const p = m.person ? idx.person[m.person] : null;
    const tms = p ? idx.termsOf[p.id] ?? [] : [];
    return {
      key: m.key,
      m,
      p,
      name: p?.name ?? m.name,
      last: p?.last,
      photo: m.photo,
      tms,
      lines: [...(p ? officeLines(p.id) : []), ...(m.offices ?? [])],
      short: p ? shortOffice(p.id) : (m.offices ?? [])[0] ?? '',
      inOffice: tms.some((tm) => tm.year === idx.latest),
    };
  }

  function famInfo(f) {
    const ms = f.members.map(memberInfo);
    const tms = ms.flatMap((x) => x.tms);
    const years = tms.map((tm) => tm.year);
    return {
      ms,
      byKey: Object.fromEntries(ms.map((x) => [x.key, x])),
      places: [...new Set(tms.map((tm) => tm.place).filter(Boolean))],
      inOffice: ms.filter((x) => x.inOffice).length,
      span: years.length ? `${Math.min(...years)}–${Math.max(...years) + TERM}` : '',
      sources: new Set(f.ties.flatMap((tie) => tie.sources.map((s) => s.url))).size,
    };
  }

  // Ties of one member, seen from that member: mine = their role, theirs = the relative's role
  const famTies = (fam, key) =>
    fam.ties
      .map((tie, i) => ({ tie, i }))
      .filter(({ tie }) => tie.a === key || tie.b === key)
      .map(({ tie, i }) => (tie.a === key ? { tie, i, other: tie.b, mine: tie.aIs, theirs: tie.bIs } : { tie, i, other: tie.a, mine: tie.bIs, theirs: tie.aIs }));

  const famOrder = () => F.families.slice().sort((a, b) => b.members.length - a.members.length || b.ties.length - a.ties.length || a.name.localeCompare(b.name));

  // ---------- Views: Families ----------

  const famState = { q: '', place: '', sort: 'members', current: false };

  function renderFamilies() {
    const y = idx.latest;
    const withFams = new Set(F.families.flatMap((f) => famInfo(f).places));
    const opt = (v, label, cur) => `<option value="${esc(v)}"${v === cur ? ' selected' : ''}>${esc(label)}</option>`;
    $('#families-body').innerHTML = `
      ${crumbs()}
      <h1 class="dy-h1">${esc(t('dy-nav-families', 'Families'))}</h1>
      <p class="dy-lede">${esc(t('dy-families-desc', 'Families with two or more members who held elected office, where a published source states how they are related.'))}</p>
      <p class="dy-note dy-note-plain">${esc(F.note)}</p>
      <div class="dy-toolbar" style="margin-top:24px">
        <div class="dy-filter">
          <label for="f-search">${esc(t('dy-fam-search', 'Find a family, a person or a place'))}</label>
          <input id="f-search" type="search" value="${esc(famState.q)}" placeholder="${esc(t('dy-fam-search-ph', 'e.g. Zubiri, Valencia'))}" autocomplete="off" />
        </div>
        <div class="dy-filter dy-filter-narrow">
          <label for="f-place">${esc(t('dy-place', 'Place'))}</label>
          <select id="f-place">${opt('', t('dy-place-all', 'All of Bukidnon'), famState.place)}${D.places
            .filter((p) => withFams.has(p.id))
            .map((p) => opt(p.id, p.name, famState.place))
            .join('')}</select>
        </div>
        <div class="dy-filter dy-filter-narrow">
          <label for="f-sort">${esc(t('dy-sort', 'Sort by'))}</label>
          <select id="f-sort">${opt('members', t('dy-sort-members', 'Most members'), famState.sort)}${opt('office', t('dy-sort-office', 'Most elected in {y}', { y }), famState.sort)}${opt(
            'name',
            t('dy-sort-name', 'Name (A–Z)'),
            famState.sort,
          )}</select>
        </div>
        <label class="dy-check"><input type="checkbox" id="f-current"${famState.current ? ' checked' : ''} /> <span>${esc(t('dy-fam-current', 'Only families with a member elected in {y}', { y }))}</span></label>
      </div>
      <p class="dy-count" id="f-count" aria-live="polite"></p>
      <div class="dy-grid dy-fam-grid" id="f-cards"></div>
      <div class="dy-empty" id="f-empty" hidden>${esc(t('dy-empty', 'Nothing matches.'))} <button type="button" class="dy-linkbtn" id="f-clear">${esc(t('dy-clear', 'Clear filters'))}</button></div>`;

    const bind = (id, key, prop = 'value') =>
      $('#' + id).addEventListener('input', (e) => {
        famState[key] = e.target[prop];
        renderFamilyCards();
      });
    bind('f-search', 'q');
    bind('f-place', 'place');
    bind('f-sort', 'sort');
    bind('f-current', 'current', 'checked');
    $('#f-clear').addEventListener('click', () => {
      Object.assign(famState, { q: '', place: '', current: false });
      renderFamilies();
      $('#f-search').focus();
    });
    renderFamilyCards();
  }

  function renderFamilyCards() {
    const y = idx.latest;
    const q = fold(famState.q.trim());
    const list = F.families
      .map((f) => ({ f, info: famInfo(f) }))
      .filter(({ f, info }) => {
        if (famState.place && !info.places.includes(famState.place)) return false;
        if (famState.current && !info.inOffice) return false;
        if (q && !fold([f.name, ...info.ms.map((x) => x.name), ...info.places.map(placeName)].join(' ')).includes(q)) return false;
        return true;
      });
    const order = famOrder().map((f) => f.id);
    const by = {
      members: (a, b) => order.indexOf(a.f.id) - order.indexOf(b.f.id),
      office: (a, b) => b.info.inOffice - a.info.inOffice || order.indexOf(a.f.id) - order.indexOf(b.f.id),
      name: (a, b) => a.f.name.localeCompare(b.f.name),
    };
    list.sort(by[famState.sort] ?? by.members);

    $('#f-count').textContent = t('dy-n-families', '{n} of {total} families', { n: list.length, total: F.families.length });
    $('#f-empty').hidden = list.length > 0;
    $('#f-cards').innerHTML = list
      .map(({ f, info }) => {
        const faces = info.ms
          .map((x) => `<li title="${esc(x.name)}">${face(x)}<span class="dy-sr">${esc(x.name)}</span></li>`)
          .join('');
        return `<article class="dy-card dy-fam-card">
          <span class="dy-label">${esc(t('dy-n-members', '{n} members · {k} ties', { n: f.members.length, k: f.ties.length }))}</span>
          <h3><a href="#/family/${esc(f.id)}">${esc(familyLabel(f))}</a></h3>
          <ul class="dy-faces">${faces}</ul>
          <p>${esc(f.summary)}</p>
          <div class="dy-card-meta">
            <span class="dy-pill${info.inOffice ? ' dy-pill-on' : ''}">${esc(
              info.inOffice ? t('dy-in-office', '{n} elected in {y}', { n: info.inOffice, y }) : t('dy-none-in-office', 'No member elected in {y}', { y }),
            )}</span>
            ${info.span ? `<span class="dy-count">${esc(info.span)}</span>` : ''}
            ${info.places.length ? `<span class="dy-count">${esc(info.places.map(placeName).join(', '))}</span>` : ''}
          </div>
        </article>`;
      })
      .join('');
  }

  // ---------- Views: Family ----------

  function renderFamily(id, sub) {
    const fam = idx.family[id];
    if (!fam) return notFound();
    const info = famInfo(fam);
    const y = idx.latest;
    const order = famOrder();
    const at = order.findIndex((f) => f.id === id);
    const prev = order[(at - 1 + order.length) % order.length];
    const next = order[(at + 1) % order.length];
    const credits = [...new Set(fam.members.filter((m) => m.photo).map((m) => m.photo.credit))];

    const memberCards = info.ms
      .map((x) => {
        const rel = famTies(fam, x.key)
          .map((r) => esc(cap(t('dy-role-of', '{role} of {name}', { role: roleLabel(r.mine).toLowerCase(), name: info.byKey[r.other].name }))))
          .join(' · ');
        const name = x.p ? `<a class="dy-person" href="#/person/${esc(x.p.id)}">${esc(x.name)}</a>` : `<strong>${esc(x.name)}</strong>`;
        return `<article class="dy-member" data-key="${esc(x.key)}">
          ${face(x, 'dy-face-lg')}
          <div class="dy-member-body">
            <h3 class="dy-h3">${name}</h3>
            ${x.inOffice ? `<span class="dy-pill dy-pill-on">${esc(t('dy-current', 'Elected in {y}', { y }))}</span>` : ''}
            <p class="dy-member-offices">${x.lines.map(esc).join('<br>') || `<span class="dy-none">${esc(t('dy-no-office', 'No elected office on record'))}</span>`}</p>
            ${x.m.note ? `<p class="dy-sub">${esc(x.m.note)}</p>` : ''}
            ${rel ? `<p class="dy-member-rel">${rel}</p>` : ''}
            <button type="button" class="dy-linkbtn" data-show="${esc(x.key)}">${esc(t('dy-show-in-diagram', 'Show in diagram'))}</button>
          </div>
        </article>`;
      })
      .join('');

    $('#family-body').innerHTML = `
      ${crumbs(['#/families', t('dy-nav-families', 'Families')])}
      <h1 class="dy-h1">${esc(familyLabel(fam))}</h1>
      <p class="dy-lede">${esc(fam.summary)}</p>

      <dl class="dy-stats dy-stats-sm">
        <div><dt class="dy-label">${esc(t('dy-members-label', 'Members'))}</dt><dd class="dy-stat">${fam.members.length}</dd></div>
        <div><dt class="dy-label">${esc(t('dy-stat-ties', 'Documented ties'))}</dt><dd class="dy-stat">${fam.ties.length}</dd></div>
        <div><dt class="dy-label">${esc(t('dy-current', 'Elected in {y}', { y }))}</dt><dd class="dy-stat dy-stat-accent">${info.inOffice}</dd></div>
        <div><dt class="dy-label">${esc(t('dy-stat-span', 'Years in office'))}</dt><dd class="dy-stat">${esc(info.span || '–')}</dd></div>
      </dl>
      ${
        info.places.length
          ? `<p class="dy-places"><span class="dy-label">${esc(t('dy-places-label', 'Where they held office'))}</span>${info.places
              .map((p) => `<a class="dy-chip dy-chip-muted" href="#/place/${esc(p)}">${esc(placeName(p))}</a>`)
              .join('')}</p>`
          : ''
      }

      <section class="dy-block" id="dg-section">
        <div class="dy-block-head">
          <h2 class="dy-section-h">${esc(t('dy-diagram', 'How They Are Related'))}</h2>
          <button type="button" class="dy-btn dy-btn-sm" id="dg-fit" hidden></button>
        </div>
        <p class="dy-block-sub">${esc(t('dy-diagram-hint', 'Select a person or a connecting line to see their offices and the sources.'))}</p>
        <div class="dy-diagram" id="dg">${diagram(fam, info)}</div>
        <p class="dy-scroll-hint" id="dg-hint" hidden>${esc(t('dy-scroll-hint', 'Scroll sideways to see everyone'))} <span aria-hidden="true">→</span></p>
        <p class="dy-legend">
          <span><i class="dy-key dy-key-line"></i>${esc(t('dy-legend-parent', 'parent and child, siblings, other'))}</span>
          <span><i class="dy-key dy-key-dash"></i>${esc(t('dy-legend-spouse', 'married'))}</span>
          <span><i class="dy-key dy-key-now"></i>${esc(t('dy-legend-now', 'elected in {y}', { y }))}</span>
          ${fam.members.some((m) => !m.person) ? `<span><i class="dy-key dy-key-out"></i>${esc(t('dy-legend-out', 'dashed box: no elected office in Bukidnon on record'))}</span>` : ''}
        </p>
        <div class="dy-focus" id="dg-focus" aria-live="polite"></div>
        ${credits.length ? `<p class="dy-credit">${esc(t('dy-portraits', 'Portraits:'))} ${esc(credits.join('; '))}</p>` : ''}
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-timeline', 'Offices Over Time'))}</h2>
        <p class="dy-block-sub">${esc(t('dy-timeline-note', 'Each column is an election; a term runs three years. Hover a cell for the office and place.'))}</p>
        ${timeline(fam, info)}
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-members', 'Members and Offices'))}</h2>
        <div class="dy-members">${memberCards}</div>
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-ties-sources', 'Ties and Sources'))}</h2>
        <ul class="dy-ties">${fam.ties.map((tie, i) => tieItem(fam, tie, { i, bare: true })).join('')}</ul>
      </section>

      ${
        order.length > 1
          ? `<nav class="dy-famnav" aria-label="${esc(t('dy-family-nav', 'More families'))}">
        <a href="#/family/${esc(prev.id)}"><span class="dy-label">← ${esc(t('dy-prev-family', 'Previous family'))}</span>${esc(familyLabel(prev))}</a>
        <a href="#/families" class="dy-famnav-all">${esc(t('dy-all-families', 'All families'))}</a>
        <a href="#/family/${esc(next.id)}" class="dy-famnav-next"><span class="dy-label">${esc(t('dy-next-family', 'Next family'))} →</span>${esc(familyLabel(next))}</a>
      </nav>`
          : ''
      }`;
    wireFamily(fam, info, sub);
  }

  // Members × elections grid
  function timeline(fam, info) {
    const used = new Set();
    const rows = info.ms
      .filter((x) => x.p)
      .map((x) => {
        const cells = D.years
          .map((y) => {
            const tms = x.tms.filter((tm) => tm.year === y);
            const cur = y === idx.latest ? ' dy-tl-cur' : '';
            if (!tms.length) return `<td class="dy-tl-cell${cur}"></td>`;
            for (const tm of tms) used.add(tm.position);
            const title = tms.map((tm) => `${posLabel(tm.position)}${tm.place ? `, ${placeName(tm.place)}` : ''} (${y}–${y + TERM})`).join('; ');
            const lvl = PROVINCIAL.has(tms[0].position) ? 'prov' : 'local';
            return `<td class="dy-tl-cell${cur}"><span class="dy-tl-on dy-tl-${lvl}" title="${esc(title)}"><span aria-hidden="true">${esc(
              tms.map((tm) => t(...SHORT[tm.position])).join('/'),
            )}</span><span class="dy-sr">${esc(title)}</span></span></td>`;
          })
          .join('');
        return `<tr data-key="${esc(x.key)}"><th scope="row" class="dy-tl-name"><button type="button" class="dy-tl-who" data-show="${esc(x.key)}">${face(x, 'dy-face-sm')}<span>${esc(
          x.name,
        )}</span></button></th>${cells}</tr>`;
      })
      .join('');
    const legend = Object.keys(SHORT)
      .filter((p) => used.has(p))
      .map((p) => `<span><b class="dy-tl-on dy-tl-${PROVINCIAL.has(p) ? 'prov' : 'local'}">${esc(t(...SHORT[p]))}</b> ${esc(posLabel(p))}</span>`)
      .join('');
    return `<div class="dy-table-wrap dy-tl-wrap"><table class="dy-tl">
      <thead><tr><th scope="col" class="dy-tl-name">${esc(t('dy-col-name', 'Name'))}</th>${D.years
        .map((y) => `<th scope="col"${y === idx.latest ? ' class="dy-tl-cur"' : ''}>${y}</th>`)
        .join('')}</tr></thead>
      <tbody>${rows}</tbody></table></div>
      <p class="dy-legend dy-tl-legend">${legend}</p>`;
  }

  // Plain or linked sentence for one tie
  function tieSentence(fam, tie, linkFn) {
    const a = memberName(fam, tie.a);
    const b = memberName(fam, tie.b);
    const tpl =
      tie.aIs === 'relative'
        ? t('dy-tie-related', '{a} and {b} are related.', { a: '@@A@@', b: '@@B@@' })
        : t('dy-tie-sentence', '{a} is the {role} of {b}.', { a: '@@A@@', role: roleLabel(tie.aIs).toLowerCase(), b: '@@B@@' });
    if (!linkFn) return tpl.replace('@@A@@', a).replace('@@B@@', b);
    return esc(tpl).replace('@@A@@', linkFn(tie.a, a)).replace('@@B@@', linkFn(tie.b, b));
  }

  // Interactions on the family page: select a person or a tie in the diagram, the member
  // cards or the timeline; the focus panel, highlights and URL (#/family/id/key) follow.
  function wireFamily(fam, info, sub) {
    const body = $('#family-body');
    const box = $('#dg');
    const svg = box.querySelector('svg');
    const focus = $('#dg-focus');
    const fitBtn = $('#dg-fit');
    const hint = $('#dg-hint');
    let fit = false;

    function size() {
      if (!document.body.contains(box)) return;
      const natural = Number(svg.getAttribute('width'));
      const over = natural > box.clientWidth + 1;
      fitBtn.hidden = !over && !fit;
      svg.style.width = fit ? '100%' : '';
      svg.style.height = fit ? 'auto' : '';
      fitBtn.textContent = fit ? t('dy-actual-size', 'Actual size') : t('dy-fit', 'Fit to screen');
      fitBtn.setAttribute('aria-pressed', String(fit));
      hint.hidden = !over || fit;
    }

    function centerOn(key, smooth) {
      if (box.scrollWidth <= box.clientWidth) return;
      const node = svg.querySelector(`.dy-node[data-key="${CSS.escape(key)}"] rect`);
      if (!node) return;
      const r = node.getBoundingClientRect();
      const b = box.getBoundingClientRect();
      box.scrollTo({ left: box.scrollLeft + r.left + r.width / 2 - (b.left + b.width / 2), behavior: smooth ? 'smooth' : 'auto' });
    }

    let sel = null;
    function select(next, { center = false, smooth = true } = {}) {
      sel = next;
      const on = new Set();
      const onTies = new Set();
      if (sel?.type === 'p') {
        on.add(sel.key);
        for (const r of famTies(fam, sel.key)) {
          on.add(r.other);
          onTies.add(r.i);
        }
      } else if (sel?.type === 't') {
        const tie = fam.ties[sel.i];
        on.add(tie.a);
        on.add(tie.b);
        onTies.add(sel.i);
      }
      svg.classList.toggle('dy-has-sel', !!sel);
      for (const n of svg.querySelectorAll('.dy-node')) {
        const isSel = sel?.type === 'p' && n.dataset.key === sel.key;
        n.classList.toggle('is-on', on.has(n.dataset.key));
        n.classList.toggle('is-sel', isSel);
        n.setAttribute('aria-pressed', String(isSel));
      }
      for (const e of svg.querySelectorAll('.dy-edge-g')) {
        e.classList.toggle('is-on', onTies.has(Number(e.dataset.tie)));
        e.setAttribute('aria-pressed', String(sel?.type === 't' && Number(e.dataset.tie) === sel.i));
      }
      for (const el of body.querySelectorAll('.dy-member, .dy-tl tbody tr')) el.classList.toggle('is-on', sel?.type === 'p' && el.dataset.key === sel.key);
      for (const li of body.querySelectorAll('.dy-ties > li[data-tie]')) li.classList.toggle('is-on', onTies.has(Number(li.dataset.tie)));
      focus.innerHTML = focusHtml(fam, info, sel);
      focus.classList.toggle('is-open', !!sel);
      const hash = `#/family/${fam.id}${sel ? '/' + (sel.type === 'p' ? sel.key : 'tie-' + sel.i) : ''}`;
      if (location.hash !== hash) history.replaceState(null, '', hash);
      if (center && sel) centerOn(sel.type === 'p' ? sel.key : fam.ties[sel.i].a, smooth);
    }

    const pick = (el) => {
      const n = el.closest('.dy-node');
      if (n) return { type: 'p', key: n.dataset.key };
      const e = el.closest('.dy-edge-g');
      if (e) return { type: 't', i: Number(e.dataset.tie) };
      return null;
    };
    const same = (a, b) => a && b && a.type === b.type && a.key === b.key && a.i === b.i;
    svg.addEventListener('click', (ev) => {
      const next = pick(ev.target);
      select(same(next, sel) ? null : next);
    });
    svg.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape') return select(null);
      if (ev.key !== 'Enter' && ev.key !== ' ') return;
      const next = pick(ev.target);
      if (!next) return;
      ev.preventDefault();
      select(same(next, sel) ? null : next);
    });
    focus.addEventListener('click', (ev) => {
      const k = ev.target.closest('[data-sel-key]');
      const tie = ev.target.closest('[data-sel-tie]');
      if (ev.target.closest('[data-clear]')) select(null);
      else if (k) select({ type: 'p', key: k.dataset.selKey }, { center: true });
      else if (tie) select({ type: 't', i: Number(tie.dataset.selTie) }, { center: true });
    });
    body.onclick = (ev) => {
      const b = ev.target.closest('[data-show]');
      if (!b) return;
      select({ type: 'p', key: b.dataset.show });
      $('#dg-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
      setTimeout(() => centerOn(b.dataset.show, true), 350);
    };
    document.addEventListener(
      'keydown',
      function onEsc(ev) {
        if (!document.body.contains(box)) return document.removeEventListener('keydown', onEsc);
        if (ev.key === 'Escape' && sel && !ev.target.closest?.('input,select,textarea')) select(null);
      },
    );
    fitBtn.addEventListener('click', () => {
      fit = !fit;
      size();
    });
    onResize = size;

    size();
    let initial = null;
    if (sub?.startsWith('tie-') && fam.ties[Number(sub.slice(4))]) initial = { type: 't', i: Number(sub.slice(4)) };
    else if (sub && info.byKey[sub]) initial = { type: 'p', key: sub };
    select(initial);
    centerOn(initial?.type === 'p' ? initial.key : initial ? fam.ties[initial.i].a : fam.members[0].key, false);
  }

  function focusHtml(fam, info, sel) {
    if (!sel) return `<p class="dy-focus-empty">${esc(t('dy-focus-empty', 'Select a person or a connecting line in the diagram.'))}</p>`;
    const close = `<button type="button" class="dy-focus-close" data-clear aria-label="${esc(t('dy-close', 'Close'))}">×</button>`;
    const personBtn = (key, role) => {
      const x = info.byKey[key];
      return `<button type="button" class="dy-relbtn" data-sel-key="${esc(key)}">${face(x, 'dy-face-sm')}<span>${
        role ? `<span class="dy-tie-role">${esc(roleLabel(role))}</span>` : ''
      }<span class="dy-relbtn-name">${esc(x.name)}</span><span class="dy-relbtn-office">${esc(x.short)}</span></span></button>`;
    };
    if (sel.type === 't') {
      const tie = fam.ties[sel.i];
      return `<div class="dy-focus-head"><span class="dy-label">${esc(t('dy-focus-tie', 'Documented Tie'))}</span>${close}</div>
        <p class="dy-tie-who">${tieSentence(fam, tie, (k, n) => `<strong>${esc(n)}</strong>`)}</p>
        ${tie.note ? `<p class="dy-note">${esc(tie.note)}</p>` : ''}
        ${sourcesHtml(tie.sources)}
        <div class="dy-focus-people">${personBtn(tie.a)}${personBtn(tie.b)}</div>`;
    }
    const x = info.byKey[sel.key];
    const rel = famTies(fam, sel.key);
    return `<div class="dy-focus-person">
      ${face(x, 'dy-face-xl')}
      <div class="dy-focus-main">
        <div class="dy-focus-head"><h3 class="dy-h3">${esc(x.name)}</h3>${close}</div>
        ${x.inOffice ? `<span class="dy-pill dy-pill-on">${esc(t('dy-current', 'Elected in {y}', { y: idx.latest }))}</span>` : ''}
        <p class="dy-member-offices">${x.lines.map(esc).join('<br>') || `<span class="dy-none">${esc(t('dy-no-office', 'No elected office on record'))}</span>`}</p>
        ${x.m.note ? `<p class="dy-sub">${esc(x.m.note)}</p>` : ''}
        ${x.p ? `<a class="dy-focus-profile" href="#/person/${esc(x.p.id)}">${esc(t('dy-open-profile', 'Open full profile'))} <span aria-hidden="true">→</span></a>` : ''}
      </div>
    </div>
    <p class="dy-label dy-focus-rel-h">${esc(t('dy-focus-relatives', 'Relatives in This Family'))}</p>
    <ul class="dy-focus-rel">${rel
      .map(
        (r) => `<li>${personBtn(r.other, r.theirs)}<button type="button" class="dy-linkbtn" data-sel-tie="${r.i}">${esc(t('dy-see-source', 'Source'))} (${
          r.tie.sources.length
        })</button></li>`,
      )
      .join('')}</ul>`;
  }

  // Layered family diagram: parents above children, spouses and siblings side by side.
  // Every person and every line is focusable and selectable.
  function diagram(fam, info) {
    const gen = {};
    const keys = fam.members.map((m) => m.key);
    gen[keys[0]] = 0;
    const UP = new Set(['father', 'mother', 'parent', 'father-in-law', 'mother-in-law', 'uncle', 'aunt']);
    const DOWN = new Set(['son', 'daughter', 'child', 'son-in-law', 'daughter-in-law', 'nephew', 'niece']);
    const UP2 = new Set(['grandfather', 'grandmother']);
    const DOWN2 = new Set(['grandson', 'granddaughter']);
    const delta = (role) => (UP.has(role) ? -1 : DOWN.has(role) ? 1 : UP2.has(role) ? -2 : DOWN2.has(role) ? 2 : 0);
    for (let pass = 0; pass < keys.length + 1; pass++) {
      for (const tie of fam.ties) {
        // aIs describes A relative to B: A "father" → A is one generation above B
        if (gen[tie.a] != null && gen[tie.b] == null) gen[tie.b] = gen[tie.a] - delta(tie.aIs);
        else if (gen[tie.b] != null && gen[tie.a] == null) gen[tie.a] = gen[tie.b] + delta(tie.aIs);
      }
      for (const k of keys) if (gen[k] == null && pass === keys.length) gen[k] = 0;
    }
    const min = Math.min(...keys.map((k) => gen[k] ?? 0));
    const rows = [];
    // Within a row, keep people tied to each other (spouses, siblings) side by side.
    const sameRow = (k) => fam.ties.filter((x) => (x.a === k || x.b === k) && gen[x.a] === gen[x.b]).map((x) => (x.a === k ? x.b : x.a));
    const placed = new Set();
    for (const start of keys) {
      if (placed.has(start)) continue;
      const stack = [start];
      while (stack.length) {
        const k = stack.shift();
        if (placed.has(k)) continue;
        placed.add(k);
        (rows[(gen[k] ?? 0) - min] ??= []).push(k);
        stack.unshift(...sameRow(k).filter((x) => !placed.has(x)));
      }
    }
    const W = 192;
    const H = 58;
    const GX = 56; // wide enough for a "married" / "brother" label between neighbours
    const GY = 66;
    const PAD = 6;
    const width = Math.max(...rows.map((r) => r?.length ?? 0)) * (W + GX) - GX + PAD * 2;
    const pos = {};
    rows.forEach((r, ri) => {
      const rowW = r.length * (W + GX) - GX;
      const x0 = (width - rowW) / 2;
      r.forEach((k, i) => (pos[k] = { x: x0 + i * (W + GX), y: 10 + ri * (H + GY) }));
    });
    const height = rows.length * (H + GY) - GY + 56; // room for arcs under the last row
    const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

    const edges = fam.ties
      .map((tie, i) => {
        const a = pos[tie.a];
        const b = pos[tie.b];
        if (!a || !b) return '';
        const spouse = ['husband', 'wife', 'spouse'].includes(tie.aIs);
        let d;
        let lx;
        let ly;
        let label;
        let anchor = 'middle';
        if (a.y === b.y) {
          const [l, r] = a.x < b.x ? [a, b] : [b, a];
          if (r.x - l.x <= W + GX) {
            d = `M${l.x + W} ${l.y + H / 2} L${r.x} ${r.y + H / 2}`;
            ly = l.y + H / 2 - 6;
          } else {
            // Not neighbours: arc under the boxes instead of running behind them
            const y0 = l.y + H;
            d = `M${l.x + W / 2} ${y0} C${l.x + W / 2} ${y0 + 34}, ${r.x + W / 2} ${y0 + 34}, ${r.x + W / 2} ${y0}`;
            ly = y0 + 36;
          }
          lx = (l.x + r.x + W) / 2;
          label = spouse ? t('dy-legend-spouse', 'married') : roleLabel(tie.aIs).toLowerCase();
        } else {
          const [top, bot] = a.y < b.y ? [a, b] : [b, a];
          const my = top.y + H + GY / 2;
          d = `M${top.x + W / 2} ${top.y + H} L${top.x + W / 2} ${my} L${bot.x + W / 2} ${my} L${bot.x + W / 2} ${bot.y}`;
          // Label the lower person's role next to their line ("son", "nephew")
          label = roleLabel(bot === b ? tie.bIs : tie.aIs).toLowerCase();
          lx = bot.x + W / 2 + 6;
          ly = bot.y - 8;
          anchor = 'start';
        }
        return `<g class="dy-edge-g" data-tie="${i}" tabindex="0" role="button" aria-pressed="false" aria-label="${esc(tieSentence(fam, tie))}">
          <title>${esc(tieSentence(fam, tie))}</title>
          <path class="dy-edge-hit" d="${d}"/>
          <path class="dy-edge${spouse ? ' dy-edge-spouse' : ''}" d="${d}"/>
          <text class="dy-edge-label" x="${lx}" y="${ly}" text-anchor="${anchor}">${esc(label)}</text></g>`;
      })
      .join('');

    const nodes = info.ms
      .map((x) => {
        const p = pos[x.key];
        const out = !x.p;
        const fx = p.x + 8;
        const fy = p.y + 8;
        const img = x.photo
          ? `<image href="${esc(x.photo.url)}" x="${fx}" y="${fy}" width="34" height="42" preserveAspectRatio="xMidYMid slice" clip-path="url(#dy-clip-${esc(x.key)})"/>
             <clipPath id="dy-clip-${esc(x.key)}"><rect x="${fx}" y="${fy}" width="34" height="42"/></clipPath>`
          : '';
        const tip = [x.name, ...x.lines].join('\n');
        return `<g class="dy-node${out ? ' dy-node-out' : ''}${x.inOffice ? ' dy-node-now' : ''}" data-key="${esc(x.key)}" tabindex="0" role="button" aria-pressed="false" aria-label="${esc(
          [x.name, x.short].filter(Boolean).join(', '),
        )}">
          <title>${esc(tip)}</title>
          <rect class="dy-node-box" x="${p.x}" y="${p.y}" width="${W}" height="${H}"/>
          <rect class="dy-node-face" x="${fx}" y="${fy}" width="34" height="42"/>
          <text class="dy-node-ini" x="${fx + 17}" y="${fy + 25}" text-anchor="middle">${esc(initials(x.name, x.last))}</text>
          ${img}
          <text class="dy-node-name" x="${p.x + 52}" y="${p.y + 25}">${esc(short(x.name, 20))}</text>
          <text class="dy-node-office" x="${p.x + 52}" y="${p.y + 42}">${esc(short(x.short, 25))}</text>
          ${x.inOffice ? `<circle class="dy-node-dot" cx="${p.x + W - 10}" cy="${p.y + 10}" r="4"/>` : ''}
        </g>`;
      })
      .join('');
    return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="group" aria-label="${esc(t('dy-diagram', 'How They Are Related'))}">${edges}${nodes}</svg>`;
  }

  // ---------- Views: Officials ----------

  const PAGE = 50;
  let page = 1;

  function renderOfficials() {
    const q = fold($('#o-search').value.trim());
    const pos = $('#o-position').value;
    const place = $('#o-place').value;
    const onlyTied = $('#o-tied').checked;
    const list = D.people.filter((p) => {
      if (q && !fold(p.name).includes(q) && !p.ballots.some((b) => fold(b).includes(q))) return false;
      if (onlyTied && !idx.tiesOf[p.id]?.length) return false;
      const tms = idx.termsOf[p.id] ?? [];
      if (pos && !tms.some((tm) => tm.position === pos)) return false;
      if (place && !tms.some((tm) => tm.place === place)) return false;
      return true;
    });
    list.sort((a, b) => a.last.localeCompare(b.last) || a.name.localeCompare(b.name));
    const pages = Math.max(1, Math.ceil(list.length / PAGE));
    page = Math.min(page, pages);
    $('#o-count').textContent = t('dy-n-results', '{n} officials', { n: list.length.toLocaleString() });
    $('#o-results').innerHTML = list
      .slice((page - 1) * PAGE, page * PAGE)
      .map((p) => {
        const fams = [...(idx.familiesOf[p.id] ?? [])];
        return `<li><span>${personLink(p.id)}</span><span class="dy-chips">${fams.map(familyChip).join('')}</span>
          <p class="dy-sub">${esc(officeLines(p.id).join(' · '))}</p></li>`;
      })
      .join('');
    pager(pages);
  }

  function pager(pages) {
    const nav = $('#o-pager');
    if (pages <= 1) return (nav.innerHTML = '');
    const btn = (n, label = n, current = false, disabled = false) =>
      `<button type="button" data-page="${n}" ${current ? 'aria-current="page"' : ''} ${disabled ? 'disabled' : ''}>${label}</button>`;
    const nums = [];
    for (let n = 1; n <= pages; n++) {
      if (n === 1 || n === pages || Math.abs(n - page) <= 1) nums.push(btn(n, n, n === page));
      else if (nums.at(-1) !== '<span>…</span>') nums.push('<span>…</span>');
    }
    nav.innerHTML = btn(page - 1, '‹', false, page === 1) + nums.join('') + btn(page + 1, '›', false, page === pages);
  }

  // ---------- Views: Person ----------

  function renderPerson(id) {
    const p = idx.person[id];
    if (!p) return notFound();
    const tms = (idx.termsOf[id] ?? []).slice().sort((a, b) => b.year - a.year);
    const termRows = tms
      .map(
        (tm) => `<tr>
          <td class="dy-year">${tm.year}–${tm.year + TERM}</td>
          <td>${esc(posLabel(tm.position))}</td>
          <td>${tm.place ? `<a href="#/place/${tm.place}">${esc(placeName(tm.place))}</a>` : tm.placeCandidates ? esc(tm.placeCandidates.map(placeName).join(' or ')) : esc(t('dy-province-wide', 'Bukidnon'))}</td>
          <td class="dy-hide-sm">${esc(tm.party ?? '')}</td>
          <td class="dy-hide-sm"><span class="dy-sub" style="margin:0">${esc(tm.ballot)}</span></td>
        </tr>`,
      )
      .join('');
    const fixes = [...new Set(tms.filter((tm) => tm.fix).map((tm) => tm.fix))];

    const ties = idx.tiesOf[id] ?? [];
    const tieHtml = ties.length
      ? `<ul class="dy-ties">${ties
          .map(({ fam, tie, other, role }) => {
            const om = fam.members.find((m) => m.key === other);
            const who = om?.person ? personLink(om.person) : `<strong>${esc(om?.name ?? other)}</strong>`;
            const offices = om?.person ? officeLines(om.person) : om?.offices ?? [];
            const fx = { name: om?.person ? idx.person[om.person].name : om?.name ?? other, last: om?.person ? idx.person[om.person].last : null, photo: om?.photo };
            return `<li class="dy-tie-face">
              ${face(fx, 'dy-face-md')}
              <div>
              <span class="dy-tie-role">${esc(roleLabel(role))}</span>
              <span class="dy-tie-who">${who} <a class="dy-chip" href="#/family/${esc(fam.id)}" style="margin-left:6px">${esc(fam.name)}</a></span>
              ${offices.length ? `<span class="dy-tie-offices">${esc(offices.join(' · '))}</span>` : ''}
              ${tie.note ? `<p class="dy-note">${esc(tie.note)}</p>` : ''}
              ${sourcesHtml(tie.sources)}
              </div>
            </li>`;
          })
          .join('')}</ul>`
      : `<p class="dy-none">${esc(t('dy-no-ties-person', 'No family ties documented yet. If you know of one with a published source, report it.'))}</p>`;

    // Same surname elsewhere in Bukidnon offices, excluding documented relatives
    const relIds = new Set(ties.map((x) => x.fam.members.find((m) => m.key === x.other)?.person).filter(Boolean));
    const peers = D.people.filter((o) => o.id !== id && fold(o.last) === fold(p.last) && !relIds.has(o.id));

    $('#person-body').innerHTML = `
      ${crumbs(['#/officials', t('dy-nav-officials', 'All Officials')])}
      <div class="dy-person-head">
        ${face({ name: p.name, last: p.last, photo: idx.photoOf?.[id] }, 'dy-face-xl')}
        <div>
          <h1 class="dy-h1">${esc(p.name)}</h1>
          <p class="dy-lede">${esc(officeLines(id).join(' · '))}</p>
          ${idx.photoOf?.[id] ? `<p class="dy-credit">${esc(t('dy-portraits', 'Portraits:'))} ${esc(idx.photoOf[id].credit)}</p>` : ''}
        </div>
      </div>

      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-relatives', 'Documented Relatives in Elected Office'))}</h2>
        ${tieHtml}
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-offices-held', 'Elected Offices in Bukidnon, 2001–2025'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr>
            <th scope="col">${esc(t('dy-col-term', 'Term'))}</th>
            <th scope="col">${esc(t('dy-position', 'Office'))}</th>
            <th scope="col">${esc(t('dy-place', 'Place'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-col-party', 'Party'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-col-ballot', 'Name in the source'))}</th>
          </tr></thead>
          <tbody>${termRows}</tbody></table></div>
        ${p.mergeNote ? `<div class="dy-note dy-note-plain"><p style="margin:0">${esc(t('dy-merge-note', 'Treated as one person:'))} ${esc(p.mergeNote)}</p>${sourcesHtml(p.mergeSources)}</div>` : ''}
        ${fixes.map((f) => `<p class="dy-note">${esc(t('dy-fix-note', 'Corrected:'))} ${esc(idx.fix[f].reason)}</p>`).join('')}
      </section>

      ${
        peers.length
          ? `<section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-same-surname', 'Same Surname, Relationship Not Documented'))}</h2>
        <p class="dy-block-sub">${esc(t('dy-same-surname-note', 'Other Bukidnon officials named {last}. A shared surname is not evidence of kinship.', { last: p.last }))}</p>
        <div class="dy-councils">${peers.map((o) => `<span>${personLink(o.id)} <span class="dy-count">${esc(officeLines(o.id)[0] ?? '')}</span></span>`).join('')}</div>
      </section>`
          : ''
      }`;
  }

  // ---------- Views: About ----------

  function renderAbout() {
    const unplaced = D.terms.filter((tm) => !tm.place && !['governor', 'vice-governor', 'representative', 'board-member'].includes(tm.position));
    $('#about-body').innerHTML = `
      ${crumbs()}
      <h1 class="dy-h1">${esc(t('dy-nav-about', 'About the Data'))}</h1>
      <div class="dy-prose" style="margin-top:16px">
        <h2 class="dy-section-h">${esc(t('dy-about-what-h', 'What Is Here'))}</h2>
        <p>${esc(t('dy-about-what', 'Every winner of a seat elected in Bukidnon from 2001 to 2025: governor, vice governor, House representatives, provincial board members, and the mayors, vice mayors and councilors of the 2 cities and 20 municipalities. On top of that, the family ties between them that a published source states.'))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-elections-h', 'Election Results'))}</h2>
        <p>${esc(t('dy-about-elections', 'Winners come from OpenHalalan, a volunteer-run dataset of Philippine national and local elections, licensed under the Open Database License (ODbL 1.0). Our cleaned copy, officials.json, is published under the same license.'))}</p>
        <p class="dy-sub" style="font-size:12px">${esc(D.source.citation)} ${extLink(D.source.doi, D.source.doi)}</p>
        <p>${esc(t('dy-about-matching', 'The source has one row per person per election. We match rows to the same person by surname and given names, ignoring accents and initials. Within one city or municipality, we also match a name whose second given name is left out ("Jose Joel" and "Jose") or whose middle name differs by a letter or two, unless that person held another seat the same year. Where a ballot nickname differs from the full name, an editor matches them by hand, cites a source where one exists, and the person page says so. Two people with the same name can still be merged by mistake; report it if you see one.'))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-ties-h', 'Family Ties'))}</h2>
        <p>${esc(t('dy-about-ties', 'A tie is listed only when a news report, official page or other published source states it, and every tie links to that source. We do not infer kinship from shared surnames; where officials share a surname without a documented tie, the person page says so plainly. Being related is not wrongdoing.'))}</p>
        <p>${esc(F.note)}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-brgy-h', 'Barangay Officials'))}</h2>
        <p>${esc(t('dy-about-brgy', 'The punong barangay, kagawads, SK chairperson and SK members of each of the 464 barangays come from the masterlist in the DILG Barangay Officials Directory, as a snapshot of who holds office now. It has no past officials, so it is kept apart from the election history. It is never used as evidence of a family tie. Phone numbers in the masterlist are not copied. A verbatim copy of the Bukidnon rows and the checksum of the file are kept in data/sources/.'))} ${extLink('https://www.dilg.gov.ph/barangay-officials-directory/index', t('dy-brgy-source', 'DILG Barangay Officials Directory'))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-fixes-h', 'Corrections to the Source'))}</h2>
        <p>${esc(t('dy-about-fixes', 'We found errors in the source rows for Bukidnon and reported them to OpenHalalan.'))} ${extLink('https://github.com/RobertRLeung/OpenHalalan/issues/5', 'OpenHalalan #5')}</p>
        <ul>${D.fixes.map((f) => `<li>${esc(f.reason)}</li>`).join('')}</ul>
        <p>${esc(t('dy-about-gaps', 'Races with no winners in the source:'))} ${esc(
          [...new Set(D.gaps.map((g) => `${placeName(g.place)} ${g.year}`))].join(', '),
        )}.</p>
        <p>${esc(t('dy-about-unplaced', '{n} councilor and vice mayor terms are filed under the wrong place and could not be placed with certainty; they are shown on both possible places.', { n: unplaced.length }))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-correct-h', 'Report a Correction'))}</h2>
        <p>${esc(t('dy-about-correct', 'If something is wrong or missing, open an issue on GitHub or email us, and include a link to a published source.'))}
          ${extLink('https://github.com/Better-Bukidnon/officials/issues/new', 'GitHub')} · <a href="mailto:volunteer@betterbukidnon.org">volunteer@betterbukidnon.org</a></p>
      </div>`;
  }

  function notFound() {
    show('about');
    $('#about-body').innerHTML = `<p class="dy-empty">${esc(t('dy-not-found', 'That page does not exist.'))} <a href="#/">${esc(t('dy-nav-home', 'Home'))}</a></p>`;
    setTitle();
  }

  // ---------- Router ----------

  function show(view, nav = view) {
    for (const s of document.querySelectorAll('.dy-view')) s.hidden = s.dataset.view !== view;
    for (const a of document.querySelectorAll('.dy-subnav a')) {
      if (a.dataset.nav === nav) {
        a.setAttribute('aria-current', 'page');
        // On a phone the tabs scroll sideways; bring the current one into view.
        const bar = a.parentElement;
        if (a.offsetLeft < bar.scrollLeft || a.offsetLeft + a.offsetWidth > bar.scrollLeft + bar.clientWidth) bar.scrollLeft = a.offsetLeft - 16;
      } else a.removeAttribute('aria-current');
    }
  }

  // The tab title names the page: "Barangay Sumpong · Bukidnon Officials"
  const SITE_TITLE = 'Bukidnon Officials';
  function setTitle() {
    const view = document.querySelector('.dy-view:not([hidden])');
    const h1 = view && view.dataset.view !== 'home' && view.querySelector('h1');
    document.title = h1 ? `${h1.textContent.trim()} · ${SITE_TITLE}` : `${SITE_TITLE} · Better Bukidnon`;
  }

  function route() {
    onResize = null;
    const [, view = '', arg, sub] = (location.hash || '#/').split('/');
    const go = {
      '': () => (show('home'), renderHome()),
      places: () => (show('mayors', 'places'), renderMayors()),
      mayors: () => (show('mayors', 'places'), renderMayors()), // old links
      place: () => (show('place', 'places'), renderPlace(decodeURIComponent(arg ?? ''))),
      barangay: () => (show('barangay', 'places'), renderBarangay(decodeURIComponent(arg ?? ''))),
      province: () => (show('province'), renderProvince()),
      families: () => (show('families'), renderFamilies()),
      family: () => (show('family', 'families'), renderFamily(decodeURIComponent(arg ?? ''), sub && decodeURIComponent(sub))),
      officials: () => (show('officials'), renderOfficials()),
      person: () => (show('person', 'officials'), renderPerson(decodeURIComponent(arg ?? ''))),
      about: () => (show('about'), renderAbout()),
    }[view];
    (go ?? notFound)();
    setTitle();
  }

  function fillSelects() {
    const dist = $('#m-district');
    for (const d of [...new Set(D.places.map((p) => p.district))]) dist.insertAdjacentHTML('beforeend', `<option value="${d}">${esc(t('dy-district-n', '{d} district', { d }))}</option>`);
    const pos = $('#o-position');
    for (const p of D.positions) pos.insertAdjacentHTML('beforeend', `<option value="${p}">${esc(posLabel(p))}</option>`);
    const pl = $('#o-place');
    for (const p of D.places) pl.insertAdjacentHTML('beforeend', `<option value="${p.id}">${esc(p.name)}</option>`);
  }

  async function init() {
    const today = $('#today');
    if (today) today.textContent = new Date().toLocaleDateString('en-PH', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    try {
      [D, F] = await Promise.all(['data/officials.json', 'data/families.json'].map((u) => fetch(u).then((r) => (r.ok ? r.json() : Promise.reject(new Error(u))))));
    } catch (e) {
      $('#loading').textContent = t('dy-load-failed', 'Could not load the data. Please reload the page.');
      return;
    }
    $('#loading').hidden = true;
    buildIndex();
    fillSelects();
    const built = new Date(D.generatedAt).toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
    $('#built').textContent = ` · ${t('dy-built', 'Built {when}', { when: built })} · ${t('dy-ties-updated', 'ties reviewed {when}', { when: F.updated })}`;

    for (const id of ['m-search', 'm-district', 'm-tied']) $('#' + id).addEventListener('input', renderMayors);
    for (const id of ['o-search', 'o-position', 'o-place', 'o-tied'])
      $('#' + id).addEventListener('input', () => {
        page = 1;
        renderOfficials();
      });
    $('#o-pager').addEventListener('click', (e) => {
      const b = e.target.closest('button[data-page]');
      if (!b || b.disabled) return;
      page = Number(b.dataset.page);
      renderOfficials();
      $('#o-results').scrollIntoView({ block: 'start' });
    });
    window.addEventListener('resize', () => onResize?.());
    window.addEventListener('hashchange', () => {
      route();
      if (!location.hash.startsWith('#/officials')) window.scrollTo(0, 0);
    });
    renderHomeFinder();
    I18N?.onChange(() => {
      fillSelectsLabels();
      renderHomeFinder();
      route();
    });
    route();
  }

  function renderHomeFinder() {
    const el = $('#home-finder');
    const q = $('#hf-q')?.value ?? '';
    el.innerHTML = finderHtml('hf', { big: true });
    $('#hf-q').value = q;
    wireFinder('hf');
  }

  function fillSelectsLabels() {
    for (const o of $('#m-district').options) if (o.value) o.textContent = t('dy-district-n', '{d} district', { d: o.value });
    for (const o of $('#o-position').options) if (o.value) o.textContent = posLabel(o.value);
  }

  init();
})();
